import ContextManager from "#core/ui/context-manager/context-manager.js";
import { DisplayHandlerBase } from "#core/ui/context-manager/display-handler.js";
import {
	DisplayHideOptions,
	DisplayQueueManager,
	IDisplayRequest,
	IDisplayRequestBase,
} from "#core/ui/context-manager/display-queue-manager.js";
import { PlotCoord } from "#core/ui/utilities/utilities-plotcoord.js";

import getAdviceManager from "#base/ui/advice/advice-manager.js";
import { NotificationID, NotificationModel } from "#base/ui/notification-train/model-notification-train.js";
import { PopupPriority } from "#base/ui/popup-sequencer/popup-priority.js";
import TutorialItem, {
	TutorialAdvisorType,
	TutorialAnchorPosition,
	TutorialCalloutType,
	TutorialDefinition,
	TutorialLevel,
} from "#base/ui/tutorial/tutorial-item.js";

export interface WatchOutPopupData extends IDisplayRequestBase {
	item: TutorialItem;
}

/**
 * The main class of the watch out notification system.
 */
class WatchOutManagerClass extends DisplayHandlerBase<WatchOutPopupData> {
	private static instance: WatchOutManagerClass | null = null;
	private isNotificationPanelRaised = false;

	currentWatchOutPopupData: WatchOutPopupData | null = null;

	get isManagerActive(): boolean {
		return Configuration.getUser().tutorialLevel >= TutorialLevel.WarningsOnly;
	}

	constructor() {
		super("WatchOutManager", 8500);

		if (WatchOutManagerClass.instance) {
			console.error("Only one instance of the WatchOut manager class can exist at a time!");
		}
		WatchOutManagerClass.instance = this;
	}

	isShowing(): boolean {
		// Check if is in the DOM
		return ContextManager.hasInstanceOf("screen-watch-out");
	}

	/**
	 * @implements {IDisplayQueue}
	 */
	show(request: WatchOutPopupData): void {
		this.currentWatchOutPopupData = request;
		ContextManager.push("screen-watch-out", { singleton: true });
	}

	/**
	 * @implements {IDisplayQueue}
	 */
	hide(_request: WatchOutPopupData, _options?: DisplayHideOptions): void {
		this.currentWatchOutPopupData = null;
		ContextManager.pop("screen-watch-out");
		this.isNotificationPanelRaised = false;
	}

	canShow(_request: WatchOutPopupData, _activeRequests: readonly IDisplayRequest[]): boolean {
		return !ContextManager.hasInstanceOf("screen-watch-out");
	}

	closePopup = () => {
		if (this.currentWatchOutPopupData) {
			DisplayQueueManager.close(this.currentWatchOutPopupData);
			this.isNotificationPanelRaised = false;
		}
	};

	public raiseNotificationPanel(
		notificationId: NotificationID,
		advisorType?: TutorialAdvisorType,
		lookAtCallback?: (notificationId: NotificationID) => void,
	) {
		const adviceManager = getAdviceManager();
		if (
			!this.isManagerActive &&
			advisorType !== undefined &&
			!adviceManager.isFollowed(adviceManager.getAdvisorTypeFromTutorialAdvisorType(advisorType))
		) {
			NotificationModel.manager.dismiss(notificationId);
			return;
		}
		if (this.isShowing() || this.isNotificationPanelRaised) {
			console.warn(
				"watch-out-manager: raiseNotificationPanel(): A blocking notification " +
					notificationId.id +
					" cannot be added to the display queue, dismiss the previous before.",
			);
			return;
		}

		const type: number | null = Game.Notifications.getType(notificationId);
		if (!type) {
			console.error(
				`Tutorial: Cannot push a notification with an invalid type for notification id: ${notificationId}`,
			);
			return;
		}

		const name: string = Game.Notifications.getTypeName(type) || type.toString();
		const message: string = Game.Notifications.getMessage(notificationId) || "";
		const summary: string = Game.Notifications.getSummary(notificationId) || "";
		const notification: Notification | null = Game.Notifications.find(notificationId);
		const location: PlotCoord | undefined = notification?.Location;
		let advicePageId: string | undefined = undefined;

		// Check if there is advice associated with this warning notification,
		// If so we may want an optional redirect to specific advice in the Advisor panel, if this is tied to an advisor.
		// In most cases this will be used instead of the 'Take Me There' map location redirect from the advisor warning popup.
		const adviceID: number | undefined = notification?.AdviceType;
		if (adviceID != undefined && adviceID != -1) {
			const adviceInfo: AdviceInstanceDefinition | null = GameInfo.AdviceInstances.lookup(adviceID);
			if (adviceInfo != null) {
				if (adviceInfo.AdviceID) {
					advicePageId = adviceInfo.AdviceID;
				}
			}
		}

		const calloutDismiss = {
			callback: () => {
				// Should not allow multiple tutorial elements activation. Any way to hide a notification without dismissing?
				// Use the notification model to dismiss, so that any script side dismiss code is called
				NotificationModel.manager.dismiss(notificationId);
			},
			text: "LOC_TUTORIAL_CALLOUT_DISMISS",
			actionKey: "inline-cancel",
			closes: true,
		};

		const calloutTakeMe = {
			callback: () => {
				const notification: Notification | null = Game.Notifications.find(notificationId);
				if (location && PlotCoord.isValid(location)) {
					Camera.lookAtPlot(location);
				} else if (advicePageId != undefined) {
					ContextManager.push("screen-advisor-council", {
						createMouseGuard: true,
						singleton: true,
						attributes: { "tab-id": advisorType, "page-id": advicePageId },
					});
				} else if (lookAtCallback && notification) {
					lookAtCallback(notificationId);
				}
				NotificationModel.manager.dismiss(notificationId);
			},
			text:
				location && PlotCoord.isValid(location)
					? "LOC_TUTORIAL_CALLOUT_TAKE_ME"
					: "LOC_TUTORIAL_CIVILOPEDIA_TELL_ME_MORE",
			actionKey: "inline-accept",
			closes: true,
		};

		const hasLocationContent = notification?.Location != undefined && PlotCoord.isValid(notification?.Location);
		const hasAdvicePageContent = advicePageId != undefined;
		const hasExtraContent: boolean = hasLocationContent || hasAdvicePageContent;
		const dialogTutorialDef: TutorialDefinition = {
			ID: name,
			callout: {
				title: message,
				advisor: {
					text: summary,
				},
				advisorType: advisorType || TutorialAdvisorType.Default,
				anchorPosition: TutorialAnchorPosition.MiddleRight,
				type: TutorialCalloutType.NOTIFICATION,
				option1: hasExtraContent ? calloutTakeMe : calloutDismiss, // TODO: should take us to a point in the map or screen
				option2: hasExtraContent ? calloutDismiss : undefined,
			},
		};

		const TutorialData: TutorialItem = new TutorialItem(dialogTutorialDef);
		const watchOutPopupData: WatchOutPopupData = {
			category: this.getCategory(),
			item: TutorialData,
			priority: PopupPriority.beforeCinematics,
		};
		this.isNotificationPanelRaised = true;
		this.addDisplayRequest(watchOutPopupData);
	}
}

const WatchOutManager = new WatchOutManagerClass();
export { WatchOutManager as default };

DisplayQueueManager.registerHandler(WatchOutManager);
